Add({
	kind = "figure",
	id = "gryphon-master-talonaxe",
	title = "Gryphon Master Talonaxe",
	aliases = { "Talonaxe" },
	subtitle = "Master of the Aerie Peak Aviary",
	tier = "B",
	region = "the-hinterlands",
	npc = { 5636 },
	allegiance = "Wildhammer Clan",
