		{ type = "target" },
	},
	hint = "Climb to the aviary of Aerie Peak and speak with its master.",
	sections = {
		{
			title = "Summary",
			text = [=[Gryphon Master Talonaxe keeps the great aviary of {link:aerie-peak}Aerie Peak{/link}. He knows every gryphon in the clan's flocks and every rider who has ever flown one. He remembers their names long after others have forgotten, and he keeps a soft spot in his heart for the {link:explorers-league}Explorers' League{/link}, for his own father was among the dwarves who first uncovered {link:uldaman}Uldaman{/link}.]=],
		},
		{
			title = "Significance",
			text = [=[The gryphons are the strength of the Wildhammers, and Talonaxe is their keeper. When a gryphon is lost, the whole clan feels it. When the heir of the aviary's greatest gryphon vanished, it was Talonaxe who would not rest until the young one was found. His story shows how closely the fate of the dwarves is bound to the fate of their beasts.]=],
		},
		{
			title = "Deeds",
			text = [=[• He trains the gryphons of {link:aerie-peak}Aerie Peak{/link} and assigns their riders.
• He once lent his finest rider, {link:rhapsody-shindigger}Rhapsody Shindigger{/link}, to the explorer {link:brohann-caskbelly}Brohann Caskbelly{/link} for a flight over the {link:swamp-of-sorrows}Swamp of Sorrows{/link}.
• He let Rhapsody go when drink took hold of him after that flight.
• He led the search for Sharpbeak, from the {link:witherbark-trolls}Witherbark{/link} cages to the {link:the-altar-of-zul}Altar of Zul{/link}.
• He sent to a Wildhammer diviner in the {link:blasted-lands}Blasted Lands{/link} when all other searches failed.]=],
		},
	},
	chapters = {
		{
			key = "the-rider-who-fell",
