			hint = [=[Learn from the gryphon master what became of the rider sent with Brohann.]=],
			unlock = {
				{ type = "quest", id = 1450 },
			},
			text = [=[Talonaxe remembered the flight at once. He had sent his best rider to fly with {link:brohann-caskbelly}Brohann{/link} over the swamp in search of a drowned temple. The rider was {link:rhapsody-shindigger}Rhapsody Shindigger{/link}, and no one in the aviary could fly like him. But Rhapsody came back from that flight shaken and thirsty, and his thirst only grew. In the end the master of the aviary had to send him away.]=],
		},
		{
			key = "the-lost-heir",
			title = "The Lost Heir",
			hint = [=[Search the troll villages and the Altar of Zul for a missing young gryphon.]=],
			unlock = {
				{ type = "quest", id = 2988 },
				{ type = "quest", id = 2989 },
			},
			text = [=[Sharpbeak, the heir of the aviary's mightiest gryphon, vanished while he hunted with his parents. Talonaxe was sure that trolls had taken him. The cages of the {link:witherbark-trolls}Witherbark{/link} villages were searched and found empty. {link:the-altar-of-zul}The Altar of Zul{/link}, where the Vilebranch make their sacrifices, was searched next. The young gryphon was not there either, and Talonaxe did not know whether to grieve or rejoice.]=],
		},
		{
			key = "a-feather-and-a-diviner",
			title = "A Feather and a Diviner",
			hint = [=[Carry a feather from Sharpbeak's nest to the diviner of Nethergarde.]=],
			unlock = {
				{ type = "quest", id = 2990 },
			},
			text = [=[With every trail gone cold, Talonaxe turned to {link:thadius-grimshade}Thadius Grimshade{/link}. Grimshade had left {link:aerie-peak}Aerie Peak{/link} years before to seek darker knowledge, but Talonaxe still called him a Wildhammer at heart. A feather from the nest where the young gryphon had slept was sent to the diviner's tower, so that he might follow its thread back to its owner.]=],
		},
		{
			key = "the-cage-on-the-cliff",
			title = "The Cage on the Cliff",
			hint = "Bring home the young gryphon held by the Vilebranch.",
			unlock = {
				{ type = "quest", id = 2994 },
			},
			text = [=[{link:thadius-grimshade}Grimshade{/link}'s divination found Sharpbeak in a cage high on a cliff at {link:jintha-alor}Jintha'Alor{/link}. The key hung at the belt of the {link:vile-priestess-hexx}Vile Priestess Hexx{/link}. The Wildhammers could not bear it. The priestess fell, the cage was opened, and Sharpbeak flew home to his parents. Talonaxe watched them fuss over their child, and the old {link:dwarves}dwarf{/link}'s eyes were not dry.]=],
		},
	},
